# Generated by build.py from recipe.yml for recipe signalr-receive-a-message. Do not edit.
Set-Location $PSScriptRoot
$server0 = Start-Process surl -ArgumentList '--allow-anonymous', 'signalr://127.0.0.1:8080/' -PassThru -NoNewWindow
Start-Sleep 1
try { curl.exe -s -S -d "{\"type\":1,\"target\":\"Broadcast\",\"arguments\":[\"hello from surl\"]}" signalr://127.0.0.1:8080/ } finally { Stop-Process $server0 }
